%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;
NG_FFCutsFits = recover_selected_cuts('NG_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

fit_res_field = 'all_fit_par';
separate_fig  = false; % if true, detach figures from live script

%%
[S_op110,J_op110,G_op110,Sq_op110,proj110minFF]= display_EiDep_blocks(NG_FFCutsFits, ... %[output:group:5e2a3821] %[output:4d84e212] %[output:0e3eec81] %[output:3c99ec2b]
    'off110NGminFF',' <110> min FF change',fit_res_field,separate_fig); %[output:group:5e2a3821] %[output:4d84e212] %[output:0e3eec81] %[output:3c99ec2b]


[S_maEi800,J_maEi800,Gam_maEi800,S_maEi800q] = extract_fit_par( ...
    NG_FFCutsFits.(['Ei800_off200NGmaxFF_',fit_res_field]));
proj200maxFF = NG_FFCutsFits.Ei200_off200NGmaxFF.data.proj;

plot_fp(separate_fig,'min FF change for low dE max FF for Ei800', ... %[output:group:7b4e549a] %[output:51575c16] %[output:42ed33b8] %[output:3c52dd20]
    [S_op110,S_maEi800], ... %[output:51575c16] %[output:42ed33b8] %[output:3c52dd20]
    [J_op110,J_maEi800], ... %[output:51575c16] %[output:42ed33b8] %[output:3c52dd20]
    [G_op110,Gam_maEi800]); %[output:group:7b4e549a] %[output:51575c16] %[output:42ed33b8] %[output:3c52dd20]
%%
bg_dataNGEi200 = extract_bg_par(NG_FFCutsFits.(['Ei200_off110NGminFF_',fit_res_field]),1);
bg_dataNGEi400 = extract_bg_par(NG_FFCutsFits.(['Ei400_off110NGminFF_',fit_res_field]),1);
bg_dataNGEi800mi = extract_bg_par(NG_FFCutsFits.(['Ei800_off110NGminFF_',fit_res_field]),1);
bg_dataNGEi800ma = extract_bg_par(NG_FFCutsFits.(['Ei800_off200NGmaxFF_',fit_res_field]),1);

plot_fp(separate_fig,'line-q fit bg for different Ei',[], ... %[output:group:981d7022] %[output:2956d259]
    [bg_dataNGEi200,bg_dataNGEi400,bg_dataNGEi800mi,bg_dataNGEi800ma]) %[output:group:981d7022] %[output:2956d259]
%%
spp.Ei200_off110NGminNbg = NG_FFCutsFits.Ei200_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei200_off110NGminFF,@linterp_bg,bg_dataNGEi200);
spp.Ei200_off110NGminNbg = cut(spp.Ei200_off110NGminNbg, ... %[output:group:6bc58a26] %[output:0d129073] %[output:12434628]
    [-0.35,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0])) %[output:group:6bc58a26] %[output:0d129073] %[output:12434628]
plot(spp.Ei200_off110NGminNbg); lz 0 1; keep_figure %[output:13a06135]
%%

spp.Ei400_off110NGminNbg = NG_FFCutsFits.Ei400_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei400_off110NGminFF,@linterp_bg,bg_dataNGEi400);
spp.Ei400_off110NGminNbg = cut(spp.Ei400_off110NGminNbg,[-0.5,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0])) %[output:4c718e8e] %[output:62e6fead]
plot(spp.Ei400_off110NGminNbg); lz 0 1; keep_figure %[output:992c6b99]

spp.Ei800_off110NGminNbg = NG_FFCutsFits.Ei800_off110NGminFF - ...
    sqw_eval(NG_FFCutsFits.Ei800_off110NGminFF,@linterp_bg,bg_dataNGEi800mi);
spp.Ei800_off110NGminNbg = cut(spp.Ei800_off110NGminNbg, ... %[output:group:4a246886] %[output:6e2009b9]
    [-0.5,0.005,0],[],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0])); %[output:group:4a246886] %[output:6e2009b9]
plot(spp.Ei800_off110NGminNbg); lz 0 1; keep_figure %[output:648e0eac]
%%

spp.Ei800_off200NGmaxNbg = NG_FFCutsFits.Ei800_off200NGmaxFF - ...
    sqw_eval(NG_FFCutsFits.Ei800_off200NGmaxFF,@linterp_bg,bg_dataNGEi800ma);
spp.Ei800_off200NGmaxNbg = cut(spp.Ei800_off200NGmaxNbg, ... %[output:group:3960c684] %[output:39f45763] %[output:669e1754]
    [-0.5,0.005,0],[],SymopReflection('normvec',[1,1,0],'offset',[2,0,0])) %[output:group:3960c684] %[output:39f45763] %[output:669e1754]
plot(spp.Ei800_off200NGmaxNbg); lz 0 0.1; keep_figure %[output:569ffc81]
%%


%%
cuts_rangesNG = containers.Map();
cuts_rangesNG('Ei200_off110NGminNbg')  = [0;110];
cuts_rangesNG('Ei400_off110NGminNbg') = [110;170];
cuts_rangesNG('Ei800_off110NGminNbg') = [170;250];
cuts_rangesNG('Ei800_off200NGmaxNbg') = [250;390];

[w2,fh] = build_disp_in_dir_with_ds(spp,cuts_rangesNG,[-0.5,0.005,0],false); %[output:22478e11] %[output:50ceceaf]
data_ranges = cuts_rangesNG.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
%save('NG_0p5_0p5_0_data','pan_data');
fh.UserData = w2.data;

%%

plot(spp.Ei800_off200NGmaxNbg); lz 0 0.1;keep_figure; %[output:569eea8e]
plot(fit_obj); lz 0 0.1;keep_figure; %[output:675a186a]
%[fit_obj,fit_par] = kk.simulate();
%%
if ~exist('magi','var')
    magi = MagneticIons();
end
sppCr.Ei200_off110NGminNbg= magi.correct_mag_ff(spp.Ei200_off110NGminNbg);
plot(sppCr.Ei200_off110NGminNbg); lz 0 2;keep_figure; %[output:76e25368]

sppCr.Ei400_off110NGminNbgCr = magi.correct_mag_ff(spp.Ei400_off110NGminNbg);
plot(sppCr.Ei400_off110NGminNbg); lz 0 1; keep_figure %[output:2160d809]

sppCr.Ei800_off110NGminNbg = magi.correct_mag_ff(spp.Ei800_off110NGminNbg);
plot(sppCr.Ei800_off110NGminNbg); lz 0 1; keep_figure %[output:515e4bc4]

sppCr.Ei800_off200NGmaxNbg = magi.correct_mag_ff(spp.Ei800_off200NGmaxNbg);
plot(sppCr.Ei800_off200NGmaxNbg); lz 0 1; keep_figure %[output:552bc267]

[w2,fh] = build_disp_in_dir_with_ds(sppCr,cuts_rangesNG,0.01,0.5,false); %[output:3192a9ef] %[output:486800d7]
data_ranges = cuts_rangesNG.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
save('NG_0p5_0p5_0_data','pan_data');

%%
gamma=10;Seff0=0.7917;
%J0=39; J1=35; % GP
J0 = 52; J1 = 20; %  NG
correct_ff = 1;
gap = 0;    %
init_fg_param = [correct_ff,8,gamma,Seff0,  0,   J0, J1,  0,  0,  0];
%init_fg_params = [coffect_ff,T,gamma,Seff, gap, J0, J1, J2, J3, J4];
free_sw_param  =  [0          0, 1   ,1   , 0,    1, 1,   0,  0,  0];


keys = cuts_rangesNG.keys();
n_cuts = 0;
cut_ranges = struct();
for keyIndex = 1:numel(keys)
    currentKey = keys{keyIndex};
    range = cuts_rangesNG(currentKey);
    min_range = 30;
    if contains(currentKey,'Ei400')
        min_range = 40;
    end
    if contains(currentKey,'Ei800')
        min_range = 70;
    end    
    if range(1)<min_range
        range(1) = min_range;
    end
    cut_ranges.(currentKey) = range; 
    n_cuts = n_cuts + floor(range(2)-range(1))/10;
end
cuts = cell(1,n_cuts);
cutIdx = 0;
en = zeros(1,n_cuts);
for keyIndex = 1:numel(keys)
    currentKey = keys{keyIndex};
    range = cut_ranges.(currentKey);
    ncc = floor(range(2)-range(1))/10 - 1;
    for i=1:ncc
        cutIdx =cutIdx+1;
        cuts{cutIdx} = cut(spp.(currentKey),[],[range(1)+(i-1)*10,range(1)+i*10]);
        en(cutIdx) = range(1)+5+10*(i-1);
        %plot(cuts{cutIdx});
    end
end
cuts = cuts(1:cutIdx);
%%

kk = tobyfit(cuts{:});
kk = kk.set_local_foreground;
kk = kk.set_fun(@sqw_iron);

hkl_proj = spp.Ei800_off200NGmaxNbg.data.proj;
kk = kk.set_pin({init_fg_param,hkl_proj});
kk = kk.set_free(free_sw_param);

kk = kk.set_bind({{6,[6,1]},{7,[7,1]}});

%kk = kk.set_bfun (@linear_bg1D); % set_bfun sets the background functions
%
%bg_param = init_bg_param(valid);
%kk = kk.set_bpin (bg_param);  % initial background constant and gradient
%kk = kk.set_bfree (bfree);

kk = kk.set_options('list',2);

[fit_obj,fit_par] = kk.fit(); %[output:8abdefa3] %[output:9895dbb6] %[output:7fce5229] %[output:6cf19c04] %[output:8060f05e] %[output:55e3443a] %[output:252dc767] %[output:73467e26] %[output:2b974ea5] %[output:333162a1] %[output:2f48cd9f]
%%

[Sar,J0ar,GamAr,J1ar] = extract_multicut_fit_par(fit_par,en);
pd(Sar); keep_figure %[output:3e54023a]
pd(J0ar); keep_figure %[output:5c95bb35]
pd(GamAr);ly 0 200; keep_figure; %[output:8f50b737]
pd(J1ar);keep_figure; %[output:13dbec46]

